branch-prediction.pseudocode:
# 2비트 포화 카운터: 0·1=Not Taken, 2·3=Taken
class TwoBitPredictor:
    def __init__(self, size):
        self.size = size
        self.pht = [1] * size  # 약한 Not Taken으로 시작

    def predict(self, pc):
        return self.pht[pc % self.size] >= 2  # True=Taken

    def update(self, pc, taken):
        i = pc % self.size
        if taken:
            self.pht[i] = min(3, self.pht[i] + 1)
        else:
            self.pht[i] = max(0, self.pht[i] - 1)

