brewer-nash-model.pseudocode:
# history[user]: 사용자가 이미 읽은 객체 목록
def can_read(user, obj, history):
    for h in history[user]:
        if h.company == obj.company:
            return True  # 이미 접근한 회사: 허용
    for h in history[user]:
        if h.coi_class == obj.coi_class:
            return False  # 같은 충돌 클래스 경쟁사: 차단
    return True  # 충돌 클래스 첫 접근: 허용

def read(user, obj, history):
    if not can_read(user, obj, history):
        raise PermissionError('Chinese Wall')
    history[user].append(obj)  # 이력이 벽을 형성

def can_write(user, obj, history):
    # *-속성: 타사 비공개 데이터를 읽은 적 없어야 쓰기
    if not can_read(user, obj, history):
        return False
    return all(h.company == obj.company or h.sanitized
               for h in history[user])

