# POLICY: (역할, 행위) → 허용 여부, 명시된 것만 허용
def authorize(user, action, resource):
    if not POLICY.get((user.role, action), False):
        return deny(user, action, resource)  # 수직 상승 차단
    is_owner = resource.owner_id == user.id
    if not is_owner and user.role != 'admin':
        return deny(user, action, resource)  # IDOR 차단
    return True

def deny(user, action, resource):
    log_warning(user.id, action, resource.id)  # 탐지용 로그
    return False  # 기본 거부
